export function documentFromTemplate(template: BuiltinTemplate, locale: TemplateLocale): TierListDocument {
  if (!template.availableLocales.includes(locale)) throw new Error(`Template ${template.id} is not available in ${locale}`);
  const doc = emptyDocument(template.title[locale] ?? template.title.en);
  return { ...doc, tiers: doc.tiers.map((tier) => tier.id === "unranked" ? { ...tier, items: template.items.map((item) => ({ id: item.id, label: item.labels?.[locale] ?? item.label, imageUrl: item.imageUrl })) } : tier) };
}

export function templatesForLocale(locale: TemplateLocale): BuiltinTemplate[] {
  return BUILTIN_TEMPLATES.filter((template) => template.availableLocales.includes(locale));
}
